 const active=(state.profiles||[]).filter(Boolean).filter(p=>p.active).length;
 return `<div class="card"><div class="row"><div><h2>Team</h2><div class="sub">${active} active · ${state.profiles.length} total employees</div></div><button id="newEmployee" class="btn primary">+ Employee</button></div>
 <div class="list" style="margin-top:14px">${(state.profiles||[]).filter(Boolean).map(p=>`<div class="job"><div class="row"><div><b>${esc(p?.full_name||"Team member")}</b><div class="sub">${esc(p.role||"employee")} ${p.email?"· "+esc(p.email):""}</div>${p.phone?`<div class="sub">${esc(p.phone)}</div>`:""}</div><div style="text-align:right"><span class="pill ${p.active?"active":""}">${p.active?"Active":"Inactive"}</span><button class="btn" data-employee="${p.id}" style="margin-left:6px">Manage</button></div></div></div>`).join("")||`<div class="empty">No employees yet.</div>`}</div></div>
 <div class="card" style="margin-top:14px"><h3>Employee access</h3><p class="sub">New employees get a Nolan Electric login. The app never stores employee passwords in the database.</p></div>`;
