function laborWeekBounds(offset=0){
 const now=new Date(); now.setHours(0,0,0,0); const day=now.getDay(); const diff=day===0?-6:1-day; const start=new Date(now); start.setDate(now.getDate()+diff+(offset*7)); const end=new Date(start); end.setDate(start.getDate()+7); return {start,end};
}
function laborPayroll(){
 const {start,end}=laborWeekBounds(state.laborWeekOffset||0); const entries=(state.companyTimeEntries||[]).filter(t=>{const d=new Date(t.started_at);return d>=start&&d<end});
 const employees=(state.profiles||[]).filter(Boolean).filter(p=>p.role!=='customer').sort((a,b)=>String(a?.full_name||'').localeCompare(String(b?.full_name||'')));
 const byEmp={}; employees.forEach(p=>byEmp[p.id]={p,hours:0,regular:0,ot:0,cost:0});
 entries.forEach(t=>{const x=byEmp[t.profile_id];if(!x)return; x.hours+=Number(t.duration_minutes||0)/60;});
 Object.values(byEmp).forEach(x=>{x.regular=Math.min(40,x.hours);x.ot=Math.max(0,x.hours-40);x.cost=x.hours*Number(state.employeeRates?.[x.p.id]||0);});
 const totalHours=entries.reduce((a,t)=>a+Number(t.duration_minutes||0)/60,0), totalOT=Object.values(byEmp).reduce((a,x)=>a+x.ot,0), totalCost=Object.values(byEmp).reduce((a,x)=>a+x.cost,0);
 const approved=entries.filter(t=>t.approved_at).length, pending=entries.length-approved;
 const weekLabel=`${start.toLocaleDateString('en-US',{month:'short',day:'numeric'})} – ${new Date(end.getTime()-86400000).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`;
 const jobName=t=>{const j=state.jobs.find(x=>x.id===t.job_id);return j?`${j.job_number||''} · ${j.name}`:'Job';};
 const rows=employees.filter(Boolean).map(x=>{const pct=Math.min(100,(x.hours/40)*100);const status=x.hours>40?'Overtime':x.hours>=36?'Near capacity':'On track';return `<div class="labor-employee-row"><div><b>${esc(x.full_name||'Employee')}</b><span>${esc(x.role||'')}</span></div><div class="labor-hours"><b>${fixed(x.hours,2)} hrs</b><small>${fixed(x.regular,2)} regular · ${fixed(x.ot,2)} OT</small><div class="labor-bar"><i style="width:${pct}%"></i></div></div><div class="labor-status ${x.hours>40?'over':x.hours>=36?'near':''}">${status}</div><div class="labor-cost">${money(x.cost)}<small>internal labor cost</small></div></div>`}).join('')||'<div class="empty">No employees found.</div>';
 const entryRows=entries.map(t=>{const p=state.profiles.find(x=>x.id===t.profile_id);const h=Number(t.duration_minutes||0)/60;return `<div class="labor-entry-row"><div><b>${esc(p?.full_name||'Employee')}</b><span>${esc(jobName(t))}</span><small>${new Date(t.started_at).toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})} · ${new Date(t.started_at).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}</small></div><strong>${fixed(h,2)}h</strong><span class="${t.approved_at?'approved-chip':'pending-chip'}">${t.approved_at?'Approved':'Needs Review'}</span><button class="btn small" data-labor-entry="${t.id}">${t.approved_at?'View':'Review'}</button></div>`}).join('')||'<div class="empty">No time entries for this week.</div>';
 return `<div class="page-heading"><div><div class="eyebrow">OPERATIONS</div><h1>Labor & Payroll</h1><p>Review field hours, labor cost, overtime and payroll-ready time.</p></div><div class="page-heading-actions"><button class="btn" id="laborPrev">← Prev Week</button><button class="btn" id="laborToday">This Week</button><button class="btn" id="laborNext">Next Week →</button><button class="btn primary" id="addManualHours">+ Add Hours</button></div></div>
 <div class="labor-week-banner"><b>${weekLabel}</b><span>${entries.length} time entries · ${pending} needing review</span></div>
 <div class="metric-grid"><div class="card metric-v2"><span>Total Hours</span><b>${fixed(totalHours,1)}</b><small>${approved} approved entries</small></div><div class="card metric-v2"><span>Overtime</span><b>${fixed(totalOT,1)}</b><small>hours over 40 / employee</small></div><div class="card metric-v2"><span>Labor Cost</span><b>${money(totalCost)}</b><small>using internal labor rates</small></div><div class="card metric-v2"><span>Review Queue</span><b>${pending}</b><small>${pending?'entries need approval':'all entries approved'}</small></div></div>
 <section class="card labor-card"><div class="section-head"><div><div class="eyebrow">CREW LABOR</div><h2>Weekly Labor Summary</h2><p class="sub">40 hours is the standard weekly threshold used for the overtime view.</p></div></div>${rows}</section>
 <section class="card labor-card"><div class="section-head"><div><div class="eyebrow">TIMESHEET REVIEW</div><h2>Time Entries</h2><p class="sub">Review individual entries before treating the week as payroll-ready.</p></div><button class="btn" id="approveLaborWeek" ${pending?'':'disabled'}>${pending?'Approve All This Week':'All Approved'}</button></div>${entryRows}</section>
 <section class="card labor-note"><b>Payroll note</b><p>This screen is a payroll-ready hours and internal labor-cost tool. It does not calculate taxes, deductions, benefits or payroll filings.</p></section>`;
}

function reports(){
 const contract=state.jobs.reduce((a,j)=>a+Number(j.contract_amount||0),0);
 const invoiced=state.invoices.reduce((a,i)=>a+Number(i.total||0),0);
 const paid=state.payments.reduce((a,p)=>a+Number(p.amount||0),0);
 const hours=state.companyTimeEntries.reduce((a,t)=>a+Number(t.duration_minutes||0)/60,0);
 const material=state.companyJobCosts.filter(c=>c.cost_type==='material').reduce((a,c)=>a+Number(c.amount||0),0);
 const overdue=state.invoices.filter(i=>i.status!=='paid'&&i.due_date&&new Date(i.due_date)<new Date()).length;
 return `<div class="page-heading"><div><div class="eyebrow">REPORTING</div><h1>Reports & Business Health</h1><p>Know what is booked, billed, collected and happening in the field.</p></div></div><div class="metric-grid"><div class="card metric-v2"><span>Contracted</span><b>${money(contract)}</b><small>${state.jobs.length} jobs</small></div><div class="card metric-v2"><span>Invoiced</span><b>${money(invoiced)}</b><small>${money(Math.max(0,invoiced-paid))} outstanding</small></div><div class="card metric-v2"><span>Collected</span><b>${money(paid)}</b><small>${overdue} overdue</small></div><div class="card metric-v2"><span>Field Hours</span><b>${fixed(hours,1)}</b><small>${money(material)} material spend</small></div></div><div class="report-grid"><section class="card report-card"><div class="eyebrow">PIPELINE</div><h2>Jobs by Status</h2>${['lead','estimate','approved','scheduled','in_progress','punch_list','complete','invoiced','paid'].map(s=>`<div class="bar-row"><span>${statusLabel(s)}</span><b>${state.jobs.filter(j=>j.status===s).length}</b><div><i style="width:${state.jobs.length?Math.max(2,state.jobs.filter(j=>j.status===s).length/state.jobs.length*100):0}%"></i></div></div>`).join('')}</section><section class="card report-card"><div class="eyebrow">FIELD REPORTS</div><h2>Recent Daily Reports</h2>${state.reports.slice(0,10).map(r=>`<div class="field-report-row"><div class="field-report-top"><b>${dateFmt(r.report_date)}</b><span>${Number(r.hours||0).toFixed(2)} hrs</span></div><div class="sub">${esc(personName(r.submitted_by))} · Submitted ${dateTimeFmt(r.created_at||r.report_date)}</div><div class="field-report-notes">${esc(r.notes||'No notes')}</div></div>`).join('')||'<div class="empty">No daily reports yet.</div>'}</section></div>`;
}
function field(){
 const today=new Date().toISOString().slice(0,10);
 const assigned=[...state.jobs].sort((a,b)=>{
  const ad=String(a.scheduled_start||"9999-99-99").slice(0,10),bd=String(b.scheduled_start||"9999-99-99").slice(0,10);
  return ad.localeCompare(bd)||String(a.name||"").localeCompare(String(b.name||""));
 });
 const todayJobs=assigned.filter(j=>String(j.scheduled_start||"").slice(0,10)===today);
 const openJobs=assigned.filter(j=>!['complete','invoiced','paid','closed'].includes(j.status));
 const activeTimer=state.timeEntries.find(t=>t.profile_id===session.user.id&&!t.ended_at);
 const todayMinutes=state.timeEntries.filter(t=>new Date(t.started_at).toDateString()===new Date().toDateString()).reduce((a,t)=>a+entryMinutes(t),0);
 const activeJobs=new Set(state.timeEntries.filter(t=>!t.ended_at).map(t=>t.job_id));
 const crewFor=j=>state.allJobMembers.filter(m=>m.job_id===j.id).map(m=>m.profiles?.full_name||personName(m.profile_id)).filter(Boolean);
 const hoursFmt=min=>{const h=Math.floor(Number(min||0)/60),m=Math.floor(Number(min||0)%60);return `${h}h ${String(m).padStart(2,'0')}m`};
 const jobRisk=j=>{
  if(!j.scheduled_end||['complete','paid','closed'].includes(j.status)) return null;
  const tasks=state.tasks.filter(t=>t.job_id===j.id),done=tasks.filter(t=>t.status==='complete').length,pct=tasks.length?done/tasks.length:0;
  const end=new Date(j.scheduled_end),now=new Date();
  if(now>end) return {label:'Behind schedule',className:'risk-bad'};
  if(end-now<2*3600000 && pct<.8) return {label:'Schedule watch',className:'risk-warn'};
  return null;
 };
 const card=j=>{
  const ts=state.tasks.filter(t=>t.job_id===j.id),done=ts.filter(t=>t.status==='complete').length,pct=ts.length?Math.round(done/ts.length*100):0;
  const crew=crewFor(j),risk=jobRisk(j),mine=activeTimer?.job_id===j.id;
  return `<article class="field-job-card ${mine?'field-job-active':''}" data-field-job-card="${j.id}">
   <button type="button" class="field-job-main" data-field-job-open="${j.id}"><div class="field-job-top"><div><span class="eyebrow">${String(j.scheduled_start||'').slice(0,10)===today?'TODAY':'ASSIGNED JOB'}</span><h3>${esc(j.name)}</h3><p>${esc(j.customers?.name||'No customer')}</p></div><span class="status-badge">${statusLabel(j.status)}</span></div>
   <div class="field-job-meta"><span><b>${done}/${ts.length}</b> tasks</span><span><b>${pct}%</b> complete</span><span>${j.scheduled_start?dateFmt(j.scheduled_start):'Not scheduled'}</span></div><div class="field-progress"><span style="width:${pct}%"></span></div>
   ${crew.length?`<div class="field-crew-line"><span>CREW</span><b>${esc(crew.slice(0,3).join(' · '))}${crew.length>3?` +${crew.length-3}`:''}</b></div>`:''}
   ${risk?`<div class="field-risk ${risk.className}">⚠ ${risk.label}</div>`:''}</button>
   <div class="field-job-actions"><button type="button" class="btn field-timer-btn ${mine?'primary':''}" data-field-timer="${j.id}">${mine?'■ STOP JOB':'▶ START JOB'}</button><button type="button" class="btn" data-field-action="note" data-field-job="${j.id}">✎ NOTE</button><button type="button" class="btn" data-field-action="photo" data-field-job="${j.id}">📷 PHOTO</button></div>
  </article>`;
 };
 const taskQueue=todayJobs.flatMap(j=>state.tasks.filter(t=>t.job_id===j.id&&!['complete','completed'].includes(String(t.status||'').toLowerCase())).map(t=>({...t,job:j}))).slice(0,5);
 const issueCount=(state.activity||[]).filter(a=>a.profile_id===session.user.id&&a.event_type==='field_issue'&&a.created_at&&(Date.now()-new Date(a.created_at).getTime())<7*86400000).length;
 return `<div class="field-dashboard v94-field-command">
 <section class="field-day-hero"><div><div class="eyebrow">FIELD COMMAND 2.0</div><h1>${dayGreeting()}</h1><p>Run the job from your phone. Start time, knock out tasks, send updates, and flag problems before they become surprises.</p></div><button class="btn" id="refresh">↻ Refresh</button></section>
 <div class="field-day-stats"><div class="card"><b>${todayJobs.length}</b><span>Today's jobs</span></div><div class="card"><b data-field-today-hours>${hoursFmt(todayMinutes)}</b><span>Hours today</span></div><div class="card"><b>${state.tasks.filter(t=>!['complete','completed'].includes(String(t.status||'').toLowerCase())).length}</b><span>Open tasks</span></div><div class="card ${activeTimer?'field-stat-live':''}"><b>${activeTimer?'LIVE':'—'}</b><span>${activeTimer?'Job timer running':'No active timer'}</span></div></div>
 <div class="field-quick-strip"><button class="btn primary" data-field-action="note">✎ ADD NOTE</button><button class="btn" data-field-action="issue">⚠ ISSUE / EXTRA WORK</button><button class="btn" data-field-action="material">▣ NEED MATERIAL</button><button class="btn" data-field-action="report">☑ DAILY REPORT</button><button class="btn" data-field-action="photo">📷 PHOTO</button></div>
 ${taskQueue.length?`<section class="field-today-work card"><div class="field-section-title"><div><div class="eyebrow">TODAY</div><h2>Today's Work</h2></div><span>${taskQueue.length}${taskQueue.length===5?'+' :''} next</span></div>${taskQueue.map(t=>`<button class="field-next-task v94-task-row" data-job="${t.job.id}"><span>□</span><span><b>${esc(t.title)}</b><small>${esc(t.job.name)}</small></span><strong>OPEN →</strong></button>`).join('')}</section>`:''}
 ${todayJobs.length?`<section><div class="field-section-title"><div><div class="eyebrow">SCHEDULE</div><h2>Today's Jobs</h2></div><span>${todayJobs.length} scheduled</span></div><div class="field-job-list">${todayJobs.map(card).join('')}</div></section>`:`<section class="field-empty card"><div class="eyebrow">TODAY</div><h2>No jobs scheduled today</h2><p>Open an assigned job below to review the work and update the office.</p></section>`}
 <section><div class="field-section-title"><div><div class="eyebrow">WORK QUEUE</div><h2>Assigned Jobs</h2></div><span>${assigned.length} total</span></div><div class="field-job-list">${assigned.map(card).join('')||'<div class="empty">No jobs assigned yet.</div>'}</div></section>
 <section class="field-field-health"><div class="field-section-title"><div><div class="eyebrow">OFFICE CONNECTION</div><h2>Keep the Office Ahead</h2></div></div><div class="field-health-grid"><button class="card" data-field-action="issue"><b>⚠ Flag an issue</b><span>${issueCount} issue${issueCount===1?'':'s'} reported this week</span></button><button class="card" data-field-action="material"><b>▣ Request material</b><span>Tell the office what you need before you stop production.</span></button><button class="card" data-field-action="report"><b>☑ Send daily report</b><span>Progress, crew, blockers and next steps in one update.</span></button></div></section>
 </div>`;
}

async function toggleFieldTimer(jobId){
 if(!session?.user?.id||!isFieldUser()||!jobId)return;
 // Re-read the active timer from Supabase so the field button never depends on stale page state.
 const activeQuery=await sb.from('time_entries').select('id,job_id,started_at').eq('profile_id',session.user.id).is('ended_at',null).order('started_at',{ascending:false}).limit(1).maybeSingle();
 if(activeQuery.error){toast('Could not check the active timer: '+activeQuery.error.message);return;}
 const active=activeQuery.data||null;
 if(active){
  if(active.job_id!==jobId){const activeJob=state.jobs.find(j=>j.id===active.job_id);toast(`Stop ${activeJob?.name||'your current job'} before starting another timer.`);return;}
  const ended=new Date();const mins=Math.max(1,Math.round((ended-new Date(active.started_at))/60000));
  const r=await sb.from('time_entries').update({ended_at:ended.toISOString(),duration_minutes:mins}).eq('id',active.id).eq('profile_id',session.user.id).select('id').maybeSingle();
  if(r.error){toast('Could not stop the job timer: '+r.error.message);return;}
  await logJobActivity(jobId,'time_entry',`Stopped timer after ${(mins/60).toFixed(2)} hours.`);
  toast('Job timer stopped.');
  await load();
  return;
 }
 const r=await sb.from('time_entries').insert({job_id:jobId,profile_id:session.user.id,started_at:new Date().toISOString()}).select().single();
 if(r.error){toast('Could not start the job timer: '+r.error.message);return;}
 await logJobActivity(jobId,'time_entry','Started job timer.');
 toast('Job timer started.');
 await load();
}

function entryMinutes(x){
 if(x.duration_minutes!=null) return Number(x.duration_minutes)||0;
 if(!x.started_at) return 0;
 return Math.max(0,Math.round((new Date(x.ended_at||Date.now())-new Date(x.started_at))/60000));
}
function jobCostingModel(j){
 const entries=(state.timeEntries||[]).filter(Boolean), costs=(state.jobCosts||[]).filter(Boolean);
 const contract=Number(j?.contract_amount||0), estLabor=Number(j?.estimated_labor_cost||0), estMat=Number(j?.estimated_material_cost||0), estOther=Number(j?.estimated_other_cost||0), estTotal=estLabor+estMat+estOther;
 const laborHours=entries.reduce((a,x)=>a+entryMinutes(x)/60,0), labor=actualLaborCost(entries);
 const materials=costs.filter(x=>x.cost_type==='material').reduce((a,x)=>a+Number(x.amount||0),0), other=costs.filter(x=>x.cost_type!=='material').reduce((a,x)=>a+Number(x.amount||0),0), actual=labor+materials+other;
 const laborHoursBudget=Number(j?.estimated_labor_hours||0), laborVariance=estLabor-labor, materialVariance=estMat-materials, otherVariance=estOther-other, variance=estTotal-actual;
 const currentProfit=contract-actual, currentMargin=contract?currentProfit/contract*100:0, projectedFinalCost=Math.max(actual,estTotal), projectedProfit=contract-projectedFinalCost, projectedMargin=contract?projectedProfit/contract*100:0;
 const tasks=(state.tasks||[]).filter(t=>t.job_id===j?.id), doneTasks=tasks.filter(t=>t.status==='complete').length, workPct=tasks.length?doneTasks/tasks.length:0, costPct=contract?actual/contract:0, burnPct=workPct>0?costPct/workPct:0;
 let health='good', healthLabel='On Track';
 if((estTotal>0&&actual>estTotal*1.1)||(workPct>0&&costPct>workPct+0.1)){health='bad';healthLabel='Needs Attention'} else if((estTotal>0&&actual>estTotal*0.9)||(workPct>0&&costPct>workPct+0.03)){health='warn';healthLabel='Watch Closely'}
 const invoiceIds=(state.invoices||[]).map(x=>x.id), invoiced=(state.invoices||[]).reduce((a,x)=>a+Number(x.total||0),0), paid=(state.payments||[]).filter(x=>invoiceIds.includes(x.invoice_id)).reduce((a,x)=>a+Number(x.amount||0),0), outstanding=Math.max(0,invoiced-paid);
 return {contract,estLabor,estMat,estOther,estTotal,laborHours,laborHoursBudget,labor,materials,other,actual,laborVariance,materialVariance,otherVariance,variance,currentProfit,currentMargin,projectedFinalCost,projectedProfit,projectedMargin,tasks,doneTasks,workPct,costPct,burnPct,health,healthLabel,invoiced,paid,outstanding};
}
function varianceClass(v){return v<0?'negative':v>0?'positive':'';}
function varianceText(v){return v<0?'−':'+';}

function actualLaborCost(entries){
 return (entries||[]).reduce((sum,x)=>sum+(entryMinutes(x)/60)*Number(state.employeeRates[x.profile_id]||0),0);
}

async function downloadFillableEstimatePDF(est,j,items){
 try{
  if(!session?.access_token){toast('Please sign in again before downloading.');return}
  toast('Building fillable PDF…');

  // V108.3 — exact approved estimate artwork.
  // The approved PDF is used as the literal visual base; we only add the four
  // AcroForm fields. This avoids rebuilding or subtly changing the customer document.
  if(String(est.estimate_number||'')==='EST-2026-001'){
   const r=await fetch('./EST-2026-001-fillable-template.pdf',{cache:'no-store'});
   if(!r.ok) throw new Error('Could not load the approved estimate template.');
   const blob=await r.blob();
   const url=URL.createObjectURL(blob);
   const a=document.createElement('a');a.href=url;a.download='EST-2026-001_Fillable.pdf';document.body.appendChild(a);a.click();a.remove();
   setTimeout(()=>URL.revokeObjectURL(url),60000);
   toast('Exact approved estimate downloaded with fillable acceptance fields.');
   return;
  }

  const payload={estimate:est,job:j,customer:j?.customers||{},property:state.properties.find(p=>p.id===j?.property_id)||{},items:items||[]};
  const r=await fetch(`${cfg.supabaseUrl}/functions/v1/generate-estimate-pdf`,{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,apikey:cfg.supabaseKey,'Content-Type':'application/json'},body:JSON.stringify(payload)});
  if(!r.ok){let msg='Could not build the fillable PDF.';try{const x=await r.json();msg=x?.error||msg}catch(_){}throw new Error(msg)}
  const blob=await r.blob();
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');a.href=url;a.download=`${String(est.estimate_number||'Estimate').replace(/[^a-zA-Z0-9._-]+/g,'_')}_Fillable.pdf`;document.body.appendChild(a);a.click();a.remove();
  setTimeout(()=>URL.revokeObjectURL(url),60000);
  toast('Fillable PDF downloaded. You can fill it on your phone and email it to the customer.');
 }catch(err){console.error('Fillable estimate PDF failed:',err);toast(err?.message||'Could not build the fillable PDF.','error')}
}

