let fieldActionSubmitting=false;
document.addEventListener("submit",async e=>{
 if(e.target.id==="askNolanForm"){
   e.preventDefault();
   const form=e.target;
   const input=form.querySelector("#askNolanInput");
   const q=input?.value?.trim()||"";
   if(!q||state.askNolanBusy)return;
   const prior=(state.askNolanMessages||[]).slice(-8).map(m=>(m.role==="user"?"USER: ":"NOLAN: ")+String(m.text||"")).join("\n");
   const imageDataUrl=state.askNolanImage?.dataUrl||null;
   const fileDataUrl=state.askNolanFile?.dataUrl||null;
   const fileName=state.askNolanFile?.name||null;
   const attachmentName=state.askNolanImage?.name||state.askNolanFile?.name||null;
   const fullQ=prior?`CONVERSATION SO FAR:\n${prior}\n\nCURRENT USER MESSAGE:\n${q}`:q;
   state.askNolanMessages=[...(state.askNolanMessages||[]),{role:"user",text:q,attachment:attachmentName}];
   state.askNolanQuestion=q;
   state.askNolanBusy=true;
   state.askNolanError="";
   state.askNolanImage=null;
   state.askNolanFile=null;
   if(input)input.value="";
   render();
   try{
     const ans=await askNolanAI(fullQ,imageDataUrl,fileDataUrl,fileName);
     state.askNolanMessages=[...state.askNolanMessages,{role:"assistant",text:String(ans?.text||"Nolan returned an empty answer."),answer:ans}];
   }catch(err){
     console.error("Ask Nolan AI error",err);
     state.askNolanError=err?.message||"Nolan could not answer right now.";
   }finally{
     state.askNolanBusy=false;
     render();
     setTimeout(()=>document.getElementById("askNolanInput")?.focus(),0);
   }
   return;
 }
 if(e.target.id!=="fieldActionForm") return;
 e.preventDefault();
 if(fieldActionSubmitting) return;
 fieldActionSubmitting=true;
 const form=e.target;
 const fd=new FormData(form);
 const getField=(name)=>fd.get(name);
 const page=currentPage();
 const action=page.action;
 const jobId=page.jobId||getField("job_id");
 if(!jobId){toast("Select a job first.");return}
 const job=state.jobs.find(j=>j.id===jobId);
 if(!job){toast("Job not found.");return}
 const button=form.querySelector(".action-submit");
 if(button){button.disabled=true;button.textContent="Saving..."}
 try{
  let r;
  if(action==="note") r=await sb.from("job_activity").insert({job_id:jobId,profile_id:session.user.id,event_type:"field_note",message:getField("message")});
  if(action==="issue") { const type=String(getField("issue_type")||"issue").toUpperCase().replaceAll("_"," "); const priority=String(getField("priority")||"normal").toUpperCase(); r=await sb.from("job_activity").insert({job_id:jobId,profile_id:session.user.id,event_type:"field_issue",message:`[${type}] [${priority}] ${getField("message")}`}); }
  if(!r.error && /EXTRA WORK|CHANGE NEEDED|HIDDEN CONDITION/i.test(String(getField("issue_type")||""))) await notifyOfficeTeam(jobId,"field_issue","Field extra work reported",`${job.name} · ${String(getField("message")||"Extra work reported").slice(0,160)}`);
  if(action==="material"){
   r=await sb.from("material_requests").insert({job_id:jobId,requested_by:session.user.id,item:getField("item"),quantity:Number(getField("quantity")||1),notes:getField("notes")});
   if(!r.error) await logJobActivity(jobId,"material_request",`Material requested: ${getField("item")}.`);
  }
  if(action==="report"){
   r=await sb.from("daily_reports").insert({job_id:jobId,submitted_by:session.user.id,report_date:getField("report_date"),hours:Number(getField("hours")||0),notes:getField("notes")});
   if(!r.error) await logJobActivity(jobId,"daily_report","Daily report added.");
  }
  if(action==="hours"){
   const hours=Number(getField("hours")||0),now=new Date().toISOString();
   r=await sb.from("time_entries").insert({job_id:jobId,profile_id:session.user.id,started_at:now,ended_at:now,duration_minutes:Math.round(hours*60),notes:getField("notes")});
   if(!r.error) await logJobActivity(jobId,"time_entry",`Logged ${fixed(hours,2)} hours.`);
  }
  if(action==="photo"){
   const file=pendingPhotoFile||form.querySelector("#actionPhotoFile")?.files?.[0]||null;
   if(!file){toast("Take or choose a photo first.");if(button){button.disabled=false;button.textContent="Upload Photo"}return}
   const path=jobId+"/"+crypto.randomUUID()+"-"+file.name.replace(/[^a-zA-Z0-9._-]/g,"_");
   const up=await sb.storage.from("job-photos").upload(path,file,{upsert:false});
   if(up.error) throw new Error("Photo upload failed: "+up.error.message);
   r=await sb.from("job_photos").insert({job_id:jobId,uploaded_by:session.user.id,storage_path:path,caption:getField("caption")||null});
   if(!r.error) await logJobActivity(jobId,"photo_added",`Job photo added${getField("caption")?`: ${getField("caption")}`:"."}`);
  }
  if(r?.error) throw r.error;
  state.selected=job;
  await load();
  navigate({type:"job",id:jobId},{replace:true});
  if(action==="photo"){if(pendingPhotoPreviewUrl){try{URL.revokeObjectURL(pendingPhotoPreviewUrl)}catch(_){} }pendingPhotoFile=null;pendingPhotoPreviewUrl=null;}
  toast(action==="photo"?"Photo uploaded.":"Saved successfully.");
  fieldActionSubmitting=false;
 }catch(err){console.error(err);toast(err?.message||"Could not save. Please try again.");if(button){button.disabled=false;button.textContent=action==="photo"?"Upload Photo":action==="material"?"Request Material":action==="report"?"Save Daily Report":action==="hours"?"Save Hours":"Save Note"} fieldActionSubmitting=false}
});

