function openMobileAccount(){
 const existing=document.querySelector('.mobile-account-sheet');if(existing){existing.remove();return;}
 const wrap=document.createElement('div');wrap.className='mobile-account-sheet';
 wrap.innerHTML=`<div class="mobile-account-backdrop"></div><section class="mobile-account-panel"><div class="mobile-account-head"><div><div class="eyebrow">ACCOUNT</div><h2>${esc(profile?.full_name||'User')}</h2></div><button class="btn" id="closeMobileAccount">Close</button></div><div class="mobile-account-card"><div class="mobile-account-avatar">${esc((profile?.full_name||'U').trim().charAt(0).toUpperCase())}</div><div><b>${esc(profile?.full_name||'User')}</b><span>${esc(profile?.role||'')}</span></div></div><button class="mobile-account-signout" id="mobileAccountLogout">Sign Out</button></section>`;
 document.body.appendChild(wrap);
 wrap.querySelector('#closeMobileAccount')?.addEventListener('click',()=>wrap.remove());wrap.querySelector('.mobile-account-backdrop')?.addEventListener('click',()=>wrap.remove());wrap.querySelector('#mobileAccountLogout')?.addEventListener('click',async()=>{const b=wrap.querySelector('#mobileAccountLogout');if(b){b.disabled=true;b.textContent='Signing Out…';}await sb.auth.signOut();});
}
function globalSearch(){navigate({type:'search',q:''});}
